// docs-kit — how-tos by role (DESIGN §4.1): the index in the front door,
// generated by `docs-kit index` and verified by `docs-kit check`.
import { readFileSync, writeFileSync } from 'node:fs';
import { join, posix } from 'node:path';
import { firstHeading, frontMatter } from './frontmatter.mjs';

export const START = '<!-- docs-kit:howtos-by-role:start -->';
export const END = '<!-- docs-kit:howtos-by-role:end -->';
export const HEADING = '## How-tos by role';
const NOTE = '<!-- Generated by `docs-kit index` from each how-to\'s `roles:` front matter. Do not edit by hand. -->';

const ARCHIVE = 'archive/';

/** Is this docs-relative path a how-to? (`<subject>/.../howto/HOWTO-<task>.md`, outside archive) */
export const isHowto = (rel) =>
  !rel.startsWith(ARCHIVE) && /(^|\/)howto\/HOWTO-[^/]+\.md$/.test(rel);

/**
 * Read every how-to: its title and roles.
 * @param files docs-relative paths
 */
export function readHowtos(root, docsRoot, files) {
  return files.filter(isHowto).map((rel) => {
    const text = readFileSync(join(root, docsRoot, rel), 'utf8');
    const fm = frontMatter(text);
    const title = (typeof fm.title === 'string' && fm.title) || firstHeading(text) ||
      posix.basename(rel, '.md').replace(/^HOWTO-/, '');
    let roles = fm.roles;
    if (typeof roles === 'string') roles = roles ? [roles] : [];
    return { rel, title, roles: roles ?? null, fm };
  });
}

const escapeText = (s) => s.replace(/([\\[\]])/g, '\\$1');
const linkPath = (rel) => rel.split('/').map((seg) => encodeURIComponent(seg)).join('/');

/** The generated block, markers included, with "\n" line endings. */
export function renderIndex(roles, howtos) {
  const lines = [START, NOTE];
  for (const role of roles) {
    lines.push('', `### ${role}`, '');
    const mine = howtos
      .filter((h) => Array.isArray(h.roles) && h.roles.includes(role))
      .sort((a, b) => a.title.localeCompare(b.title, 'en') || a.rel.localeCompare(b.rel, 'en'));
    if (!mine.length) lines.push('_No how-tos yet._');
    for (const h of mine) lines.push(`- [${escapeText(h.title)}](${linkPath(h.rel)})`);
  }
  lines.push('', END);
  return lines.join('\n');
}

/** Find the generated block in the front door. Returns null, or { start, end, text }. */
export function findIndex(readme) {
  const s = readme.indexOf(START);
  if (s === -1) return null;
  const e = readme.indexOf(END, s);
  if (e === -1) return { start: s, end: -1, text: null };
  return { start: s, end: e + END.length, text: readme.slice(s, e + END.length) };
}

const normalizeEol = (s) => s.replace(/\r\n/g, '\n');

/**
 * Role findings for the layout check.
 * Only runs when `roles` is configured; how-tos that name roles without
 * that config get a warning.
 */
export function checkRoles(root, cfg, files) {
  const errors = [];
  const warnings = [];
  const D = cfg.docsRoot;
  const howtos = readHowtos(root, D, files);
  const known = new Set(cfg.roles);

  if (!cfg.roles.length) {
    for (const h of howtos) {
      if (h.roles && h.roles.length) warnings.push(`${D}/${h.rel}: names roles, but docs-kit.json has no "roles" list`);
    }
    return { errors, warnings };
  }

  // H10: roles are configured, so there must be how-tos to index.
  if (!howtos.length) {
    errors.push(`"roles" is configured but no how-tos were found (${D}/<subject>/howto/HOWTO-<task>.md); a check that reads nothing does not pass`);
    return { errors, warnings };
  }

  for (const h of howtos) {
    if (!h.roles || !h.roles.length) {
      errors.push(`${D}/${h.rel}: no roles: in the front matter (roles: [${cfg.roles.join(', ')}])`);
      continue;
    }
    for (const r of h.roles) {
      if (!known.has(r)) errors.push(`${D}/${h.rel}: role "${r}" is not in docs-kit.json "roles" (${cfg.roles.join(', ')})`);
    }
  }

  let readme = null;
  try { readme = readFileSync(join(root, D, 'README.md'), 'utf8'); } catch { /* reported by rule 1 */ }
  if (readme !== null) {
    const found = findIndex(readme);
    if (!found) {
      errors.push(`${D}/README.md: no "${HEADING}" section; run docs-kit index`);
    } else if (found.end === -1) {
      errors.push(`${D}/README.md: "${START}" has no matching end marker`);
    } else if (normalizeEol(found.text) !== renderIndex(cfg.roles, howtos)) {
      errors.push(`${D}/README.md: "${HEADING}" does not match the how-tos' front matter; run docs-kit index`);
    }
  }
  return { errors, warnings };
}

/**
 * Write (or refresh) the generated block in the front door.
 * @returns {{ changed: boolean, created: boolean }}
 */
export function writeIndex(root, cfg, files) {
  const path = join(root, cfg.docsRoot, 'README.md');
  const readme = readFileSync(path, 'utf8');
  const eol = readme.includes('\r\n') ? '\r\n' : '\n';
  const block = renderIndex(cfg.roles, readHowtos(root, cfg.docsRoot, files)).replace(/\n/g, eol);
  const found = findIndex(readme);
  let next;
  if (!found) {
    const base = readme.replace(/(\r?\n)*$/, '');
    next = `${base}${eol}${eol}${HEADING}${eol}${eol}${block}${eol}`;
  } else if (found.end === -1) {
    throw new Error(`${cfg.docsRoot}/README.md: "${START}" has no matching end marker; fix it by hand`);
  } else {
    next = readme.slice(0, found.start) + block + readme.slice(found.end);
  }
  if (next === readme) return { changed: false, created: false };
  writeFileSync(path, next);
  return { changed: true, created: !found };
}
